generate.initial_sparql:
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?totalCashFlow ?avgProgress
WHERE {
  {
    SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?totalCashFlow)
    WHERE {
      ?cf a wm:CashFlow ;
          wm:amount ?amount ;
          wm:cashFlowOfInvestor ?inv .
      ?inv wm:investorId ?investorId .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (AVG(xsd:decimal(?progress)) AS ?avgProgress)
    WHERE {
      ?ig a wm:InvestmentGoal ;
          wm:progressPct ?progress ;
          wm:belongsToInvestor ?inv .
      ?inv wm:investorId ?investorId .
    }
    GROUP BY ?investorId
  }
  FILTER(?avgProgress < 50)
  ?inv2 wm:investorId ?investorId ;
        wm:investorName ?investorName .
}
ORDER BY DESC(?totalCashFlow)
LIMIT 10

